return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_CO','project-id-version'=>'TranslatePress Multilingual','pot-creation-date'=>'2026-10-13T10:48:01+03:00','po-revision-date'=>'2026-10-13T10:48:01+03:00','x-generator'=>'TranslatePress build (community + OpenRouter), 2026-10-13','messages'=>['TranslatePress - DEV'=>'TranslatePress - DEV','https://translatepress.com/'=>'https://translatepress.com/','Experience a better way of translating your WordPress site using a visual front-end translation editor, with full support for WooCommerce and site builders.'=>'Experimenta una mejor forma de traducir tu sitio de WordPress usando un editor de traducción visual en el front-end, con soporte completo para WooCommerce y constructores de sitios.','Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban'=>'Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban','https://cozmoslabs.com/'=>'https://cozmoslabs.com/','Active'=>'Activo','The inactive languages will still be visible and active for the admin. For other users they won\'t be visible in the language switchers and won\'t be accessible either.'=>'Los idiomas inactivos seguirán siendo visibles y activos para el administrador. Para otros usuarios no serán visibles en los selectores de idioma ni serán accesibles.','unknown'=>'desconocido','<strong>Extra Languages add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>El complemento Extra Languages</strong> requiere TranslatePress versión %1$s o superior. Actualmente está usando la versión %2$s. Actualice TranslatePress para habilitar esta función.','Dismiss this notice.'=>'Descartar este aviso.','Post Slug'=>'Slug de entrada','URL Slugs Translation'=>'Traducción de slugs de URL','Slugs'=>'Slugs','Taxonomy Slugs'=>'Slugs de taxonomía','Search Taxonomy Slugs'=>'Buscar slugs de taxonomía','Taxonomy Slug'=>'Slug de taxonomía','Translation'=>'Traducción','Term Slugs'=>'Slugs de término','Search Term Slugs'=>'Buscar slugs de término','Term Slug'=>'Slug de término','Taxonomy'=>'Taxonomía','Filter by Taxonomy'=>'Filtrar por taxonomía','Post Slugs'=>'Slugs de entrada','Search Post Slugs'=>'Buscar slugs de entrada','Post ID'=>'ID de entrada','Post Type'=>'Tipo de entrada','Filter by Post Type'=>'Filtrar por tipo de entrada','Published'=>'Publicado','Any Post Status'=>'Cualquier estado de la entrada','Post Type Base Slugs'=>'Slugs base de tipos de contenido','Post Type Base Slug'=>'Slug base de tipo de contenido','Search Post Type Base Slugs'=>'Buscar slugs base de tipos de contenido','WooCommerce Slugs'=>'Slugs de WooCommerce','WooCommerce Slug'=>'Slug de WooCommerce','Search WooCommerce Slugs'=>'Buscar slugs de WooCommerce','Automatic and manual slug translation changes performed when <strong>TranslatePress - Multilingual</strong> 2.8.4 was active had to be removed because of some issues with that version. All slug translations from before that version are now in use. Thank you for understanding!'=>'Los cambios automáticos y manuales de traducción de slugs realizados cuando <strong>TranslatePress - Multilingual</strong> 2.8.4 estaba activo tuvieron que eliminarse debido a algunos problemas con esa versión. Todas las traducciones de slugs anteriores a esa versión están ahora en uso. ¡Gracias por tu comprensión!','If you absolutely need them, the removed translations can be found in tables trp_slug_original_obsolete and trp_slug_translation_obsolete.'=>'Si absolutamente las necesita, las traducciones eliminadas se pueden encontrar en las tablas trp_slug_original_obsolete y trp_slug_translation_obsolete.','(inactive)'=>'(inactivo)','Other Slugs'=>'Otros slugs','Search Other Slugs'=>'Buscar otros slugs','Automatic User Language Detection'=>'Detección automática del idioma del usuario','Invalid language code'=>'Código de idioma no válido','We\'ve detected you might be speaking a different language. Do you want to change to:'=>'Hemos detectado que podrías estar hablando un idioma diferente. ¿Quieres cambiar a:','Change Language'=>'Cambiar idioma','Close and do not switch language'=>'Cerrar y no cambiar de idioma','First by browser language, then IP address (recommended)'=>'Primero por idioma del navegador, luego por dirección IP (recomendado)','First by IP address, then by browser language'=>'Primero por dirección IP, luego por idioma del navegador','Only by browser language'=>'Solo por idioma del navegador','Only by IP address'=>'Solo por dirección IP','A popup appears asking the user if they want to be redirected'=>'Aparece una ventana emergente preguntando al usuario si desea ser redirigido','Redirect directly (*not recommended)'=>'Redirigir directamente (*no recomendado)','Pop-up window over the content'=>'Ventana emergente sobre el contenido','Hello bar before the content'=>'Barra de notificación antes del contenido','Automatic User Language Detection requires a newer version of TranslatePress to use its visual settings interface. The legacy settings form will remain available until TranslatePress is updated.'=>'La detección automática del idioma del usuario requiere una versión más reciente de TranslatePress para usar su interfaz visual de configuración. El formulario de configuración heredado permanecerá disponible hasta que se actualice TranslatePress.','Update TranslatePress'=>'Actualizar TranslatePress','WARNING. Cannot determine your language preference based on your current IP.<br>This is most likely because the website is on a local environment.'=>'ADVERTENCIA. No se puede determinar tu preferencia de idioma a partir de tu IP actual.<br/>Esto probablemente se debe a que el sitio web está en un entorno local.','Permission denied.'=>'Permiso denegado.','Invalid nonce.'=>'Nonce no válido.','Invalid settings.'=>'Configuración no válida.','Settings saved.'=>'Ajustes guardados.','Go to <a href="%s" target="_self">Advanced</a> tab to change this feature\'s settings'=>'Ve a la pestaña <a href="%s" target="_self">Avanzado</a> para cambiar los ajustes de esta función','Website language selector'=>'Selector de idioma del sitio web','Change language'=>'Cambiar idioma','Available languages'=>'Idiomas disponibles','Please enter your DeepL API key.'=>'Por favor, ingresa tu clave API de DeepL.','DeepL'=>'DeepL','Bad request. There was an error accessing the DeepL API.'=>'Solicitud incorrecta. Hubo un error al acceder a la API de DeepL.','The API key entered is invalid.'=>'La clave de API ingresada no es válida.','The API resource could not be found.'=>'No se pudo encontrar el recurso de API.','The request size is too large.'=>'El tamaño de la solicitud es demasiado grande.','The request is too long.'=>'La solicitud es demasiado larga.','Too many requests. Please try again later.'=>'Demasiadas solicitudes. Por favor, inténtalo de nuevo más tarde.','Your translation quota has been reached.'=>'Se ha alcanzado la cuota de traducción.','We could not process your request. Please try again later.'=>'No pudimos procesar tu solicitud. Por favor, inténtalo de nuevo más tarde.','There is an error on the DeepL service and your request could not be processed.'=>'Hay un error en el servicio de DeepL y no se pudo procesar tu solicitud.','DeepL API Type'=>'Tipo de API de DeepL','Pro'=>'Pro','Free'=>'Gratis','Select the type of DeepL API you want to use.'=>'Selecciona el tipo de API de DeepL que deseas usar.','DeepL API Key'=>'Clave de API de DeepL','Visit <a href="%s" target="_blank">this link</a> to see how you can set up an API key and control API costs.'=>'Visita <a href="%s" target="_blank">este enlace</a> para ver cómo puedes configurar una clave de API y controlar los costos de la API.','No Active License Detected for this website.'=>'No se detectó una licencia activa para este sitio web.','Enter your license key'=>'Ingresa tu clave de licencia',' Or %1$spurchase one here%2$s'=>' O %1$scompra una aquí%2$s','Different Domain per Language'=>'Dominio diferente por idioma','View Docs'=>'Ver documentación','Assign different domains or subdomains to each language. When visitors access these domains, TranslatePress loads the appropriate language translation directly without redirecting.'=>'Asigne dominios o subdominios diferentes a cada idioma. Cuando los visitantes accedan a estos dominios, TranslatePress cargará directamente la traducción del idioma adecuado sin redirigir.','Example: %1$s for English, %2$s for Spanish, %3$s for French.'=>'Ejemplo: %1$s para inglés, %2$s para español, %3$s para francés.','Before enabling:'=>'Antes de habilitar:','Ensure your domains are registered, pointed to your server, and have SSL certificates configured.'=>'Asegúrate de que tus dominios estén registrados, apunten a tu servidor y tengan certificados SSL configurados.','Domain'=>'Dominio','Map this language to a different domain or sub-domain.'=>'Asigna este idioma a un dominio o subdominio diferente.','https://example.com'=>'https://example.com','Prefill with current domain'=>'Rellenar con el dominio actual','Check DNS'=>'Verificar DNS','Checking DNS...'=>'Verificando DNS...','DNS is correctly configured!'=>'¡El DNS está configurado correctamente!','DNS check failed. Please verify your domain configuration.'=>'La verificación de DNS falló. Por favor, verifica la configuración de tu dominio.','This domain is already assigned to another language.'=>'Este dominio ya está asignado a otro idioma.','<strong>Different Domain per Language add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Complemento Different Domain per Language</strong> requiere TranslatePress versión %1$s o superior. Actualmente estás usando la versión %2$s. Por favor, actualiza TranslatePress para habilitar esta función.','Note: This option is disabled when Different Domain for Language addon is active.'=>'Nota: Esta opción está desactivada cuando el complemento Different Domain for Language está activo.','Different Domain per Language: Domain is required when domain mapping is enabled. The toggle has been disabled for languages with empty domains.'=>'Different Domain per Language: Se requiere un dominio cuando la asignación de dominios está activada. El interruptor se ha desactivado para los idiomas con dominios vacíos.','Different Domain per Language: The same domain cannot be assigned to multiple languages. The toggle has been disabled for duplicate domains.'=>'Different Domain per Language: El mismo dominio no puede asignarse a varios idiomas. El interruptor se ha desactivado para los dominios duplicados.','Different Domain per Language: A language domain cannot be the same as the main site URL. The toggle has been disabled for the matching domain.'=>'Different Domain per Language: El dominio de un idioma no puede ser el mismo que la URL principal del sitio. El interruptor se ha desactivado para el dominio coincidente.','Please enter a domain.'=>'Por favor, introduce un dominio.','Invalid domain format.'=>'Formato de dominio no válido.','Could not reach domain: %s'=>'No se pudo acceder al dominio: %s','Domain is reachable!'=>'¡El dominio está accesible!','Domain returned HTTP status %d.'=>'El dominio devolvió el estado HTTP %d.','Limit this menu item to the following languages'=>'Limitar este elemento de menú a los siguientes idiomas','All Languages'=>'Todos los idiomas','Translator'=>'Traductor',' TranslatePress Settings'=>' Configuración de TranslatePress','Allow this user to translate the website.'=>'Permitir que este usuario traduzca el sitio web.','Translate Site'=>'Traducir sitio','Add-On'=>'Complemento','Deactivate'=>'Desactivar','Activate'=>'Activar','Installing...'=>'Instalando...','This add-on can not be activated back without a valid license. Are you sure you want to deactivate it?'=>'Este complemento no se puede reactivar sin una licencia válida. ¿Estás seguro de que deseas desactivarlo?','Documentation'=>'Documentación','A valid license is required to activate add-ons.'=>'Se requiere una licencia válida para activar complementos.','Activate all'=>'Activar todos','Add-ons can not be activated back without a valid license. Are you sure you want to deactivate them?'=>'Los complementos no se pueden reactivar sin una licencia válida. ¿Estás seguro de que deseas desactivarlos?','Deactivate all'=>'Desactivar todos','%1$sAdd-ons settings saved successfully%2$s'=>'%1$sConfiguración de complementos guardada correctamente%2$s','Date format'=>'Formato de fecha','Customize the date formatting per each translated language.<br/>Leave empty for default WP setting or see more information <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">here</a>'=>'Personaliza el formato de fecha para cada idioma traducido.<br/>Déjalo vacío para usar la configuración predeterminada de WP o consulta más información <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">aquí</a>','To edit an existing TranslatePress language, input the language code and fill in only the columns you want to overwrite (e.g. Language name, Flag).<br>You can also add new custom languages. They will be available under General settings, All Languages list, where the URL slug can be edited.'=>'Para editar un idioma existente de TranslatePress, introduce el código de idioma y completa solo las columnas que quieres sobrescribir (p. ej., nombre del idioma, bandera).<br>También puedes agregar nuevos idiomas personalizados. Estarán disponibles en Ajustes generales, en la lista de todos los idiomas, donde se puede editar el slug de la URL.','For custom flag, first upload the image in media library then paste the URL.<br>Changing or deleting a custom language will impact translations and site URL\'s.<br>The Language code and the ISO Code should contain only alphabetical values, numerical values, "-" and "_".<br>The ISO Codes can be found on <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Google ISO Codes</a> and <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">DeepL Target Codes</a>.'=>'Para la bandera personalizada, primero sube la imagen a la biblioteca de medios y luego pega el URL.<br>Cambiar o eliminar un idioma personalizado afectará las traducciones y las URL del sitio.<br>El código de idioma y el código ISO deben contener solo valores alfabéticos, valores numéricos, "-" y "_".<br>Los códigos ISO se pueden encontrar en <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Códigos ISO de Google</a> y <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">Códigos de destino de DeepL</a>.','Language code'=>'Código de idioma','Language name'=>'Nombre del idioma','Native name'=>'Nombre nativo','ISO Code'=>'Código ISO','Flag URL'=>'URL de la bandera','Text RTL'=>'Texto RTL','Custom language'=>'Idioma personalizado','Disable bundled plugin translations'=>'Deshabilitar traducciones incluidas del plugin','By default, TranslatePress ships its own translation files in <code>wp-content/plugins/translatepress/languages/</code> and forces WordPress to use them instead of the language packs installed automatically from translate.wordpress.org.<br/>Enable this option to disable that override. WordPress will then load the community language pack from <code>wp-content/languages/plugins/</code> (if present) and fall back to the bundled files only when no pack is available.'=>'Por defecto, TranslatePress incluye sus propios archivos de traducción en <code>wp-content/plugins/translatepress/languages/</code> y obliga a WordPress a usarlos en lugar de los paquetes de idioma instalados automáticamente desde translate.wordpress.org.<br/>Activa esta opción para deshabilitar esa sobreescritura. WordPress cargará entonces el paquete de idioma de la comunidad desde <code>wp-content/languages/plugins/</code> (si está presente) y recurrirá a los archivos incluidos solo cuando no haya ningún paquete disponible.','Disable dynamic translation'=>'Desactivar la traducción dinámica','It disables detection of strings displayed dynamically using JavaScript. <br/>Strings loaded via a server side AJAX call will still be translated.'=>'Desactiva la detección de cadenas mostradas dinámicamente mediante JavaScript. <br/>Las cadenas cargadas mediante una llamada AJAX del lado del servidor seguirán traduciéndose.','Disable translation for gettext strings'=>'Desactivar la traducción de cadenas gettext','Gettext Strings are strings outputted by themes and plugins. <br> Translating these types of strings through TranslatePress can be unnecessary if they are already translated using the .po/.mo translation file system.<br>Enabling this option can improve the page load performance of your site in certain cases. The disadvantage is that you can no longer edit gettext translations using TranslatePress, nor benefit from automatic translation on these strings.'=>'Las cadenas Gettext son cadenas generadas por temas y plugins. <br> Traducir este tipo de cadenas mediante TranslatePress puede ser innecesario si ya están traducidas usando el sistema de archivos de traducción .po/.mo.<br>Activar esta opción puede mejorar el rendimiento de carga de página de tu sitio en ciertos casos. La desventaja es que ya no podrás editar las traducciones Gettext usando TranslatePress, ni beneficiarte de la traducción automática en estas cadenas.','Gettext Strings translation is disabled'=>'La traducción de cadenas Gettext está deshabilitada','To enable it go to '=>'Para activarla ve a ','TranslatePress->Advanced Settings->Debug->Disable translation for gettext strings'=>'TranslatePress->Ajustes avanzados->Depuración->Desactivar la traducción de cadenas gettext',' and uncheck the Checkbox.'=>' y desmarca la casilla de verificación.','Dismiss'=>'Descartar','Exclude translated links from sitemap'=>'Excluir enlaces traducidos del sitemap','Do not include translated links in sitemaps generated by SEO plugins.<br/>Requires <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> SEO Pack Add-on</a> to be installed and activated.'=>'No incluir los enlaces traducidos en los sitemaps generados por plugins de SEO.<br/>Requiere tener instalado y activado el <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> SEO Pack Add-on</a>.','Disable post container tags for post title'=>'Deshabilitar etiquetas contenedoras de entrada para el título de la entrada','It disables search indexing the post title in translated languages.<br/>Useful when the title of the post doesn\'t allow HTML thus breaking the page.'=>'Deshabilita la indexación de búsqueda del título de la entrada en idiomas traducidos.<br/>Útil cuando el título de la entrada no permite HTML, lo que rompe la página.','Disable post container tags for post content'=>'Deshabilitar etiquetas contenedoras de entrada para el contenido de la entrada','It disables search indexing the post content in translated languages.<br/>Useful when the content of the post doesn\'t allow HTML thus breaking the page.'=>'Deshabilita la indexación de búsqueda del contenido de la entrada en idiomas traducidos.<br/>Útil cuando el contenido de la entrada no permite HTML, lo que rompe la página.','Do not translate certain paths'=>'No traducir ciertas rutas','Choose what paths can be translated. Supports wildcard at the end of the path.<br>For example, to exclude https://example.com/some/path you can either use the rule /some/path/ or /some/*.<br>Enter each rule on it\'s own line. To exclude the home page use {{home}}.'=>'Elige qué rutas se pueden traducir. Admite comodines al final de la ruta.<br>Por ejemplo, para excluir https://example.com/some/path puedes usar la regla /some/path/ o /some/*.<br>Introduce cada regla en su propia línea. Para excluir la página de inicio, usa {{home}}.','Exclude Paths From Translation'=>'Excluir rutas de la traducción','Translate Only Certain Paths'=>'Traducir solo ciertas rutas','Enable the hreflang x-default tag for language:'=>'Activar la etiqueta hreflang x-default para el idioma:','Enables the hreflang="x-default" for an entire language. See documentation for more details.'=>'Activa el hreflang="x-default" para un idioma completo. Consulta la documentación para más detalles.','Translate numbers and numerals'=>'Traducir números y numerales','Enable translation of numbers ( e.g. phone numbers)'=>'Activar la traducción de números (p. ej., números de teléfono)','Selector'=>'Selector','Exclude from dynamic translation'=>'Excluir de la traducción dinámica','Do not dynamically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated using JavaScript.<br/>These strings will still be translated on the server side if possible.'=>'No traducir dinámicamente cadenas encontradas en nodos HTML que coincidan con estos selectores.<br>Excluye a todos los hijos de los nodos HTML que coincidan con estos selectores de ser traducidos usando JavaScript.<br/>Estas cadenas aún se traducirán del lado del servidor si es posible.','Gettext String'=>'Cadena Gettext','Exclude Gettext Strings'=>'Excluir cadenas Gettext','Exclude these strings from being translated as Gettext strings by TranslatePress. Leave the domain empty to take into account any Gettext string.<br/>Can still be translated through po/mo files.'=>'Excluye estas cadenas de ser traducidas como cadenas Gettext por TranslatePress. Deja el dominio vacío para tener en cuenta cualquier cadena Gettext.<br/>Aún pueden traducirse mediante archivos po/mo.','Exclude selectors only from automatic translation'=>'Excluir selectores solo de la traducción automática','Do not automatically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being automatically translated.<br>Manual translation of these strings is still possible.'=>'No traducir automáticamente cadenas encontradas en nodos HTML que coincidan con estos selectores.<br>Excluye a todos los hijos de los nodos HTML que coincidan con estos selectores de ser traducidos automáticamente.<br>La traducción manual de estas cadenas aún es posible.','Exclude selectors from translation'=>'Excluir selectores de la traducción','Do not translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated.<br>These strings cannot be translated manually nor automatically.'=>'No traducir cadenas encontradas en nodos HTML que coincidan con estos selectores.<br>Excluye a todos los hijos de los nodos HTML que coincidan con estos selectores de la traducción.<br>Estas cadenas no pueden traducirse manualmente ni automáticamente.','String'=>'Cadena','Exclude strings from automatic translation'=>'Excluir cadenas de la traducción automática','Do not automatically translate these strings (ex. names, technical words...)<br>Paragraphs containing these strings will still be translated except for the specified part.'=>'No traducir automáticamente estas cadenas (ej. nombres, palabras técnicas...)<br>Los párrafos que contengan estas cadenas seguirán siendo traducidos excepto la parte especificada.','Fix broken HTML'=>'Corregir HTML roto','General attempt to fix broken or missing HTML on translated pages.<br/>'=>'Intento general de corregir el HTML roto o faltante en las páginas traducidas.<br/>','Force slash at end of home url:'=>'Forzar barra diagonal al final de la URL de inicio:','Ads a slash at the end of the home_url() function'=>'Agrega una barra diagonal al final de la función home_url()','Show Both (recommended)'=>'Mostrar ambos (recomendado)','Remove Country Locale'=>'Eliminar configuración regional de país','Remove Region Independent Locale'=>'Eliminar configuración regional independiente de región','Remove duplicate hreflang'=>'Eliminar hreflang duplicado','Choose which hreflang tags will appear on your website.<br/>We recommend showing both types of hreflang tags as indicated by <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">Google documentation</a>.<br/>Removing Country Locale when having multiple Country Locales of the same language (ex. English UK and English US) will result in showing one hreflang tag with link to just one of the region locales for that language.'=>'Selecciona qué etiquetas hreflang aparecerán en tu sitio web.<br/>Recomendamos mostrar ambos tipos de etiquetas hreflang, según lo indicado en la <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">documentación de Google</a>.<br/>Eliminar la configuración regional del país al tener múltiples configuraciones regionales de país para el mismo idioma (p. ej., inglés del Reino Unido e inglés de Estados Unidos) dará como resultado que se muestre una etiqueta hreflang con enlace a solo una de las configuraciones regionales de ese idioma.','Default (example: en-US, fr-CA, etc.)'=>'Predeterminado (ejemplo: en-US, fr-CA, etc.)','Regional (example: en, fr, es, etc.)'=>'Regional (ejemplo: en, fr, es, etc.)','HTML Lang Attribute Format'=>'Formato del atributo lang de HTML','Change lang attribute of the html tag to a format that includes country regional or not. <br>In HTML, the lang attribute (<html lang="en-US">)  should be used to  specify the language of text content so that the  browser can correctly display or process  your content (eg. for  hyphenation, styling, spell checking, etc).'=>'Cambiar el atributo lang de la etiqueta html a un formato que incluya o no la región del país. <br>En HTML, el atributo lang (<html lang="en-US">) debe usarse para especificar el idioma del contenido de texto para que el navegador pueda mostrar o procesar correctamente tu contenido (p. ej., para separación silábica, estilos, corrección ortográfica, etc.).','Load legacy Language Switcher'=>'Cargar selector de idioma heredado','Applies to all types of language switchers (floating, shortcode, and menu). When enabled, the site will revert to using the original Language Switcher configured in the General Settings tab, replacing the new customizable version. Your existing switcher settings will remain saved, but they will be ignored while this option is active.'=>'Se aplica a todos los tipos de selectores de idioma (flotante, shortcode y menú). Cuando está activado, el sitio volverá a usar el selector de idioma original configurado en la pestaña de Ajustes generales, reemplazando la nueva versión personalizable. Los ajustes existentes del selector permanecerán guardados, pero se ignorarán mientras esta opción esté activa.','Load legacy SEO Pack Add-On'=>'Cargar complemento SEO Pack heredado','In case the recent migration to the new slug rewrite is causing trouble, set this to Yes to use the old method <br> Please <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">open a support ticket</a> letting us know of the issues you are having.'=>'En caso de que la migración reciente a la nueva reescritura de slug esté causando problemas, establece esto en Sí para usar el método anterior <br> Por favor, <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">abre un ticket de soporte</a> informándonos de los problemas que estás teniendo.','Manual Translation Only'=>'Solo traducción manual','TranslatePress pro-actively scans and saves strings in the database when users access translated pages. <br>This setting disables this functionality and only allows translation and string saving when inside the Translation Editor. <br>Also disables machine translation outside the Translation Editor, giving you better control over character spending, by translating only the pages you visit in the Translation Editor.'=>'TranslatePress escanea y guarda proactivamente cadenas en la base de datos cuando los usuarios acceden a páginas traducidas. <br>Esta opción deshabilita esta funcionalidad y solo permite traducir y guardar cadenas al estar dentro del Editor de traducción. <br>También deshabilita la traducción automática fuera del Editor de traducción, dándote un mejor control sobre el gasto de caracteres, al traducir solo las páginas que visitas en el Editor de traducción.','Open language switcher only on click'=>'Abrir el selector de idioma solo al hacer clic','Open the language switcher shortcode by clicking on it instead of hovering.<br> Close it by clicking on it, anywhere else on the screen or by pressing the escape key. This will affect only the shortcode language switcher.'=>'Abre el shortcode del selector de idioma haciendo clic en él en lugar de pasar el cursor sobre él.<br> Ciérralo haciendo clic en él, en cualquier otra parte de la pantalla o presionando la tecla Escape. Esto afectará solo el shortcode del selector de idioma.','Show opposite language in the language switcher'=>'Mostrar el idioma opuesto en el selector de idioma','Transforms the language switcher into a button showing the other available language, not the current one.<br> Only works when there are exactly two languages, the default one and a translation one.<br>This will affect the shortcode language switcher and floating language switcher as well.<br> To achieve this in menu language switcher go to Appearance->Menus->Language Switcher and select Opposite Language.'=>'Transforma el selector de idioma en un botón que muestra el otro idioma disponible, no el actual.<br> Solo funciona cuando hay exactamente dos idiomas, el predeterminado y uno de traducción.<br>Esto afectará también el shortcode del selector de idioma y el selector de idioma flotante.<br> Para lograr esto en el selector de idioma de menú, ve a Apariencia->Menús->Selector de idioma y selecciona Idioma opuesto.','TranslatePress gettext database optimization failed.'=>'La optimización de la base de datos gettext de TranslatePress falló.','Retry'=>'Reintentar','TranslatePress needs to optimize its gettext database tables. Back up the database, then <a href="%s">start the optimization</a>.'=>'TranslatePress necesita optimizar las tablas de la base de datos gettext. Haz una copia de seguridad de la base de datos y luego <a href="%s">inicia la optimización</a>.','Pending gettext database optimization'=>'Optimización de la base de datos gettext pendiente','Optimize TranslatePress database tables'=>'Optimizar las tablas de la base de datos de TranslatePress','<a href="%s">Click here</a> to access the database optimization tool.'=>'<a href="%s">Haz clic aquí</a> para acceder a la herramienta de optimización de la base de datos.','It helps remove possible duplicate translations, clear unnecessary data and repair possible metadata issues.'=>'Ayuda a eliminar posibles traducciones duplicadas, limpiar datos innecesarios y reparar posibles problemas de metadatos.','<a href="%s" target="_blank">Here</a> you can observe the last 5 SQL errors relevant to TranslatePress if they exist.'=>'<a href="%s" target="_blank">Aquí</a> puedes observar los últimos 5 errores SQL relevantes para TranslatePress si existen.','Troubleshooting'=>'Solución de problemas','Exclude Gettext strings'=>'Excluir cadenas Gettext','Debug'=>'Depuración','Custom languages'=>'Idiomas personalizados','Miscellaneous options'=>'Opciones varias','Language Switcher'=>'Selector de idioma','Exclude strings & pages'=>'Excluir cadenas & páginas','Automatic Translation Memory'=>'Memoria de traducción automática','Serve same translation for similar text. The strings need to have a percentage of 95% similarity.<br>Helps prevent losing existing translation when correcting typos or making minor adjustments to the original text. <br>If a translation already exists for a very similar original string, it will automatically be used for the current original string.<br>Does not work when making changes to a text that is part of a translation block unless the new text is manually merged again in a translation block.<br>Each string needs to have a minimum of 50 characters.'=>'Aplicar la misma traducción a textos similares. Las cadenas deben tener un porcentaje de similitud del 95%.<br>Ayuda a evitar perder las traducciones existentes al corregir errores tipográficos o hacer ajustes menores al texto original. <br>Si ya existe una traducción para una cadena original muy similar, se usará automáticamente para la cadena original actual.<br>No funciona al hacer cambios en un texto que forma parte de un bloque de traducción a menos que el nuevo texto se fusione manualmente de nuevo en un bloque de traducción.<br>Cada cadena debe tener un mínimo de 50 caracteres.','WARNING: This feature can negatively impact page loading times in secondary languages, particularly with large databases (for example websites with a lot of pages or products). If you experience slow loading times, disable this and try again.'=>'ADVERTENCIA: Esta función puede afectar negativamente los tiempos de carga de la página en idiomas secundarios, particularmente con bases de datos grandes (por ejemplo, sitios web con muchas páginas o productos). Si experimentas tiempos de carga lentos, desactívala e inténtalo de nuevo.','Fix missing dynamic content'=>'Corregir contenido dinámico faltante','May help fix missing content inserted using JavaScript. <br> It shows dynamically inserted content in original language for a moment before the translation request is finished.'=>'Puede ayudar a corregir contenido faltante insertado mediante JavaScript. <br> Muestra el contenido insertado dinámicamente en el idioma original por un momento antes de que finalice la solicitud de traducción.','Filter Gettext wrapping from post content and title'=>'Filtrar la envoltura de Gettext del contenido y el título de la entrada','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post content and post title. Does not affect previous post content. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Filtra la envoltura de Gettext como #!trpst#trp-gettext de todo el contenido y título de entrada actualizados. No afecta el contenido de entrada anterior. <br/><strong>Se recomienda hacer una copia de seguridad de la base de datos antes de activar esta opción.</strong>','Filter Gettext wrapping from post meta'=>'Filtrar la envoltura de Gettext de los metadatos de la entrada','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post meta. Does not affect previous post meta. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Filtra la envoltura de Gettext como #!trpst#trp-gettext de todos los metadatos de entrada actualizados. No afecta los metadatos de entrada anteriores. <br/><strong>Se recomienda hacer una copia de seguridad de la base de datos antes de activar esta opción.</strong>','TranslatePress'=>'TranslatePress','Abilities for managing TranslatePress configuration.'=>'Capacidades para gestionar la configuración de TranslatePress.','Add a translation language'=>'Agregar un idioma de traducción','Adds a translation language to TranslatePress. Enforces the same per-license limit as the settings UI.'=>'Agrega un idioma de traducción a TranslatePress. Aplica el mismo límite por licencia que la interfaz de configuración.','WordPress locale code (e.g. fr_FR, de_DE).'=>'Código de localización de WordPress (p. ej., fr_FR, de_DE).','Optional URL slug. Defaults to the ISO language code if omitted.'=>'Slug de URL opcional. Si se omite, el valor predeterminado es el código de idioma ISO.','Set TranslatePress license key'=>'Establecer la clave de licencia de TranslatePress','Saves a TranslatePress license key and triggers a remote license check, mirroring the onboarding flow.'=>'Guarda una clave de licencia de TranslatePress y activa una verificación remota de la licencia, replicando el flujo de incorporación.','The license key to activate.'=>'La clave de licencia a activar.','Enable Automatic Translation'=>'Activar la traducción automática','Turns on Automatic Translation. A valid TranslatePress license is required only when the resolved engine is TranslatePress AI (mtapi); Google Translate and DeepL do not require one. If no engine is passed and none is configured, defaults to mtapi.'=>'Activa la traducción automática. Se requiere una licencia válida de TranslatePress solo cuando el motor resuelto es TranslatePress AI (mtapi); Google Translate y DeepL no la requieren. Si no se pasa ningún motor y no hay ninguno configurado, se usa mtapi por defecto.','Optional translation-engine slug to select (e.g. "mtapi", "google_translate_v2", "deepl"). When omitted, keeps the already-configured engine, or defaults to "mtapi" if none is configured.'=>'Slug opcional del motor de traducción para seleccionar (por ejemplo, "mtapi", "google_translate_v2", "deepl"). Cuando se omite, conserva el motor ya configurado o usa "mtapi" por defecto si no hay ninguno configurado.','List configured languages'=>'Listar idiomas configurados','Returns the languages currently configured in TranslatePress, including the default language and per-language slug/publish state.'=>'Devuelve los idiomas actualmente configurados en TranslatePress, incluido el idioma predeterminado y el estado de slug y publicación por idioma.','List available language codes'=>'Listar códigos de idioma disponibles','Returns the full catalog of language codes TranslatePress recognizes, with their English names.'=>'Devuelve el catálogo completo de códigos de idioma que reconoce TranslatePress, con sus nombres en inglés.','Remove a translation language'=>'Eliminar un idioma de traducción','Removes a configured translation language. The default language cannot be removed without first reassigning the default.'=>'Elimina un idioma de traducción configurado. No se puede eliminar el idioma predeterminado sin antes reasignarlo.','Locale code of the language to remove.'=>'Código de localización del idioma a eliminar.','Update a translation language'=>'Actualizar un idioma de traducción','Replaces the slug and publish status of an already-configured translation language.'=>'Reemplaza el slug y el estado de publicación de un idioma de traducción ya configurado.','Locale code of the language to update.'=>'Código de localización del idioma a actualizar.','URL slug for this language.'=>'Slug de URL para este idioma.','Whether this language is published on the front end.'=>'Si este idioma está publicado en el front-end.','Set the default language'=>'Establecer el idioma predeterminado','Promotes an already-configured language to be the site default. The previous default remains in the translation languages list.'=>'Promueve un idioma ya configurado para que sea el predeterminado del sitio. El idioma predeterminado anterior permanece en la lista de idiomas de traducción.','Locale code to promote to default. Must already be a configured translation language.'=>'Código de localización que se promoverá a predeterminado. Debe ser un idioma de traducción ya configurado.','You do not have permission to manage TranslatePress settings.'=>'No tienes permiso para gestionar los ajustes de TranslatePress.','Invalid language code. Allowed characters: A-Z, a-z, 0-9, hyphen, underscore.'=>'Código de idioma no válido. Caracteres permitidos: A-Z, a-z, 0-9, guion y guion bajo.','Language code "%s" is not recognized by TranslatePress.'=>'El código de idioma "%s" no es reconocido por TranslatePress.','Language "%s" is already configured.'=>'El idioma "%s" ya está configurado.','Your current license allows up to %d additional language(s). Upgrade or activate a Pro license to add more.'=>'Tu licencia actual permite hasta %d idioma(s) adicional(es). Actualiza o activa una licencia Pro para agregar más.','TranslatePress rejected the new language during settings sanitization.'=>'TranslatePress rechazó el nuevo idioma durante la sanitización de la configuración.','Enabling Automatic Translation with the TranslatePress AI engine requires an active TranslatePress license. Activate a license first with translatepress/set-license-key, or pass a different engine (e.g. "google_translate_v2", "deepl").'=>'Activar la traducción automática con el motor TranslatePress AI requiere una licencia activa de TranslatePress. Activa primero una licencia con translatepress/set-license-key, o usa un motor diferente (por ejemplo, "google_translate_v2", "deepl").','Your license key expired on %s.'=>'Tu clave de licencia venció el %s.','Your license key has expired.'=>'Tu clave de licencia ha expirado.','Your license key has been disabled.'=>'Tu clave de licencia ha sido desactivada.','Your TranslatePress license key is invalid or missing.'=>'Tu clave de licencia de TranslatePress no es válida o falta.','Your license key is disabled for this URL. Re-enable it from your TranslatePress account.'=>'Tu clave de licencia está desactivada para esta URL. Reactívala desde tu cuenta de TranslatePress.','License key mismatch. The license you entered does not match the TranslatePress version you have installed.'=>'La clave de licencia no coincide. La licencia que ingresaste no coincide con la versión de TranslatePress que tienes instalada.','Your license key has reached its activation limit.'=>'Tu clave de licencia ha alcanzado su límite de activación.','An error occurred while activating the license, please try again.'=>'Ocurrió un error al activar la licencia, por favor inténtalo de nuevo.','Language "%s" is not currently configured.'=>'El idioma "%s" no está configurado actualmente.','The default language cannot be removed. Set another language as default first.'=>'El idioma predeterminado no se puede eliminar. Establece otro idioma como predeterminado primero.','Slug is empty after sanitization. Use only URL-safe characters.'=>'El slug está vacío después de la sanitización. Usa solo caracteres seguros para URL.','Language "%s" is not currently configured. Add it first with translatepress/add-language.'=>'El idioma "%s" no está configurado actualmente. Agrégalo primero con translatepress/add-language.','The default language is always published and cannot be unpublished.'=>'El idioma predeterminado siempre está publicado y no se puede despublicar.','Slug "%1$s" is already in use by language "%2$s".'=>'El slug "%1$s" ya está en uso por el idioma "%2$s".','TranslatePress rejected the new settings during sanitization.'=>'TranslatePress rechazó la nueva configuración durante la sanitización.','Advanced'=>'Avanzado','Are you sure you want to remove this item?'=>'¿Estás seguro de que quieres eliminar este elemento?','Remove'=>'Eliminar','Add'=>'Agregar','Select...'=>'Seleccionar...','An error occurred, please try again.'=>'Ocurrió un error, por favor inténtalo de nuevo.','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Tu clave de licencia está desactivada para esta URL. Vuelve a habilitarla desde <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Administrar sitios.','<p><strong>License key mismatch.</strong> The license you entered doesn’t match the TranslatePress version you have installed.</p><p>Please check that you’ve installed the correct version for your license from your TranslatePress account.</p>'=>'<p><strong>La clave de licencia no coincide.</strong> La licencia que ingresaste no coincide con la versión de TranslatePress que tienes instalada.</p><p>Por favor, verifica que has instalado la versión correcta para tu licencia desde tu cuenta de TranslatePress.</p>','If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'Si solo tienes instalado el plugin gratuito pero agregaste una licencia de pago, instala el plugin de pago desde tu cuenta de TranslatePress.','Upgrade your plan to add more sites. %1$sUpgrade now%2$s'=>'Actualiza tu plan para agregar más sitios. %1$sActualizar ahora%2$s','You have successfully activated your license'=>'Has activado tu licencia con éxito.','[%s] Low TranslatePress AI Words'=>'[%s] Pocas palabras de TranslatePress AI','upgrade your plan'=>'actualiza tu plan','upgrade your plan or get extra AI Words'=>'actualiza tu plan u obtén palabras adicionales de TranslatePress AI','TranslatePress AI words are running low on your site.'=>'Las palabras de TranslatePress AI se están agotando en tu sitio.','Current status: %s words remaining'=>'Estado actual: %s palabras restantes','Once the remaining AI words run out, automatic translation through TranslatePress AI will be paused.'=>'Una vez que se agoten las palabras de TranslatePress AI restantes, la traducción automática mediante TranslatePress AI se pausará.','To continue translating your content, please %1$s over at %2$s'=>'Para continuar traduciendo tu contenido, por favor %1$s en %2$s','Manage Notification: %s'=>'Administrar notificación: %s','Others'=>'Otros','Restrict by Language'=>'Restringir por idioma','Exclude from Language'=>'Excluir de idioma','Restrict element to language'=>'Restringir elemento a un idioma','Show this element only in one language.'=>'Mostrar este elemento solo en un idioma.','Enable translation'=>'Habilitar traducción','Allow translation to the corresponding language only if the content is written in the default language.'=>'Permitir la traducción al idioma correspondiente solo si el contenido está escrito en el idioma predeterminado.','Select language'=>'Seleccionar idioma','Choose in which language to show this element.'=>'Elegir en qué idioma mostrar este elemento.','Exclude element from language'=>'Excluir elemento de un idioma','Exclude this element from specific languages.'=>'Excluir este elemento de idiomas específicos.','Select languages'=>'Seleccionar idiomas','Choose from which languages to exclude this element.'=>'Elegir de qué idiomas excluir este elemento.','This element will still be visible when you are translating your website through the Translation Editor.'=>'Este elemento seguirá visible cuando estés traduciendo tu sitio web mediante el Editor de traducción.','The content of this element should be written in the default language.'=>'El contenido de este elemento debe estar escrito en el idioma predeterminado.','<strong>TranslatePress</strong> encountered SQL errors. <a href="%s" title="View TranslatePress SQL Errors">Check out the errors</a>.'=>'<strong>TranslatePress</strong> encontró errores de SQL. <a href="%s" title="Ver errores de SQL de TranslatePress">Revisa los errores</a>.','Automatic translation has been disabled.'=>'La traducción automática se ha desactivado.','Logged errors'=>'Errores registrados','These are the most recent 5 errors logged by TranslatePress:'=>'Estos son los 5 errores más recientes registrados por TranslatePress:','Yes'=>'Sí','Why are these errors occuring'=>'¿Por qué ocurren estos errores?','If TranslatePress detects something wrong when executing queries on your database, it may disable the Automatic Translation feature in order to avoid any extra charging by Google/DeepL. Automatic Translation needs to be manually turned on, after you solve the issues.'=>'Si TranslatePress detecta algo incorrecto al ejecutar consultas en tu base de datos, puede desactivar la función de traducción automática para evitar cargos adicionales de Google/DeepL. La traducción automática debe activarse manualmente después de que soluciones los problemas.','The SQL errors detected can occur for various reasons including missing tables, missing permissions for the SQL user to create tables or perform other operations, problems after site migration or changes to SQL server configuration.'=>'Los errores de SQL detectados pueden ocurrir por diversas razones, incluyendo tablas faltantes, falta de permisos para que el usuario de SQL cree tablas o realice otras operaciones, problemas después de la migración del sitio o cambios en la configuración del servidor SQL.','What you can do in this situation'=>'Qué puedes hacer en esta situación','Plan A.'=>'Plan A.','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL settings. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Ve a Ajustes -> TranslatePress -> pestaña General y guarda los ajustes. Esto regenerará las tablas usando tu configuración actual de SQL. Comprueba si no ocurren más errores mientras navegas por tu sitio web en un idioma traducido. Revisa las marcas de tiempo de los errores para asegurarte de que no estás viendo los errores antiguos. Solo se muestran los 5 errores más recientes.','Plan B.'=>'Plan B.','If your problem isn\'t solved, try the following steps:'=>'Si tu problema no se resuelve, prueba los siguientes pasos:','Create a backup of your database'=>'Crea una copia de seguridad de tu base de datos','Create a copy of each translation table where you encounter errors. You can copy the table within the same database (trp_dictionary_en_us_es_es_COPY for example) -- perform this step only if you want to keep the current translations'=>'Crea una copia de cada tabla de traducción donde encuentres errores. Puedes copiar la tabla dentro de la misma base de datos (trp_dictionary_en_us_es_es_COPY, por ejemplo) -- realiza este paso solo si quieres conservar las traducciones actuales.','Remove the trouble tables by executing the DROP function on them'=>'Elimina las tablas problemáticas ejecutando la función DROP sobre ellas','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL server.'=>'Ve a Ajustes -> TranslatePress -> pestaña General y guarda los ajustes. Esto regenerará las tablas usando tu servidor SQL actual.','Copy the relevant content from the duplicated tables (trp_dictionary_en_us_es_es_COPY for example) in the newly generated table (trp_dictionary_en_us_es_es) -- perform this step only if you want to keep the current translations'=>'Copia el contenido relevante de las tablas duplicadas (trp_dictionary_en_us_es_es_COPY, por ejemplo) en la tabla recién generada (trp_dictionary_en_us_es_es) -- realiza este paso solo si quieres conservar las traducciones actuales.','Test it to see if everything is working. If something went wrong, you can restore the backup that you\'ve made at the first step. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Pruébalo para ver si todo funciona. Si algo salió mal, puedes restaurar la copia de seguridad que hiciste en el primer paso. Comprueba si no ocurren más errores mientras navegas por tu sitio web en un idioma traducido. Revisa las marcas de tiempo de los errores para asegurarte de que no estás viendo los errores antiguos. Solo se muestran los 5 errores más recientes.','Plan C.'=>'Plan C.','If your problem still isn\'t solved, try asking your hosting about your errors. The most common issue is missing permissions for the SQL user, such as the Create Tables permission.'=>'Si tu problema aún no se resuelve, intenta preguntarle a tu proveedor de alojamiento sobre los errores. El problema más común es la falta de permisos para el usuario de SQL, como el permiso Create Tables.','Could not install. Try again from <a href="%s" >Plugins Dashboard.</a>'=>'No se pudo instalar. Inténtalo de nuevo desde <a href="%s" >Escritorio de plugins.</a>','Settings scope unknown.'=>'Ámbito de configuración desconocido.','Legacy disabled.'=>'Heredado desactivado.','Change language to %s'=>'Cambiar idioma a %s','Automatic Translation'=>'Traducción automática','Unsupported languages'=>'Idiomas no compatibles','The selected automatic translation engine does not provide support for these languages.<br>You can still manually translate pages in these languages using the Translation Editor.'=>'El motor de traducción automática seleccionado no admite estos idiomas.<br>Aún puedes traducir manualmente las páginas en estos idiomas usando el editor de traducción.','General'=>'General','Glossary'=>'Glosario','API key validation failed.'=>'La validación de la clave API falló.','API key verification was successful.'=>'La verificación de la clave API fue exitosa.','Please enter your Google Translate key.'=>'Por favor, ingresa tu clave de Google Translate.','Not TranslatePress onboarding page.'=>'No es la página de bienvenida de TranslatePress.','Step %s does not exist'=>'El paso %s no existe','Welcome'=>'Bienvenida','Add Languages'=>'Agregar idiomas','Enable Addons'=>'Activar complementos','Finalize'=>'Finalizar','Exit Setup'=>'Salir de la configuración','Upgrade'=>'Actualizar','Nothing here'=>'No hay nada aquí','Your <strong>TranslatePress</strong> license is missing or invalid. <br/>Please %1$sregister your copy%2$s to enable automatic website translation via TranslatePress AI, premium addons, automatic updates and support. Need a license key? %3$sPurchase one now%4$s'=>'Tu licencia de <strong>TranslatePress</strong> no existe o no es válida. <br/>Por favor, %1$sregistra tu copia%2$s para habilitar la traducción automática del sitio web mediante TranslatePress AI, los complementos premium, las actualizaciones automáticas y el soporte. ¿Necesitas una clave de licencia? %3$sCompra una ahora%4$s','Your license is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Tu licencia está deshabilitada para esta URL. Habilítala de nuevo desde <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Administrar sitios.','You have reached the activation limit for your <strong>%1$s</strong> license. <br/>Manage your active sites from %2$s your account %3$s.'=>'Has alcanzado el límite de activaciones para tu licencia <strong>%1$s</strong>. <br/>Administra tus sitios activos desde %2$stu cuenta%3$s.','License key mismatch. The license you entered doesn’t match the <strong>%1$s</strong> version you have installed. <br/>Please check that you’ve installed the correct version for your license from your %2$sTranslatePress account%3$s.'=>'La clave de licencia no coincide. La licencia que ingresaste no coincide con la versión <strong>%1$s</strong> que tienes instalada. <br/>Por favor, verifica que hayas instalado la versión correcta para tu licencia desde tu %2$sTranslatePress Account%3$s.','<br/>If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'<br/>Si tienes solo el plugin gratuito instalado pero agregaste una licencia de pago, por favor instala el plugin de pago desde tu TranslatePress Account.','Your <strong>TranslatePress</strong> license has expired. <br/>Please %1$sRenew Your Licence%2$s to continue receiving access to automatic translations via TranslatePress AI, premium addons, product downloads, and automatic updates. %3$sRenew now %4$s'=>'Tu licencia de <strong>TranslatePress</strong> ha vencido. <br/>Por favor, %1$srenueva tu licencia%2$s para seguir recibiendo acceso a las traducciones automáticas mediante TranslatePress AI, los complementos premium, las descargas de productos y las actualizaciones automáticas. %3$sRenovar ahora %4$s','Error: '=>'Error: ','Something went wrong, please try again.'=>'Algo salió mal, por favor inténtalo de nuevo.','Your <strong>TranslatePress</strong> license will expire on %1$s. Please %2$sRenew Your Licence%3$s to continue receiving access to automatic translations via TP AI, premium addons, product downloads and automatic updates. %4$sRenew Now%5$s'=>'Tu licencia de <strong>TranslatePress</strong> vencerá el %1$s. Por favor, %2$srenueva tu licencia%3$s para mantener el acceso a las traducciones automáticas mediante TP AI, los complementos premium, las descargas de productos y las actualizaciones automáticas. %4$sRenovar ahora%5$s','Please %1$senter%2$s your license key to enable %3$s automatic translation.'=>'Por favor, %1$singresa%2$s tu clave de licencia para habilitar la traducción automática de %3$s.','%1$s automatic translation requires an active license. Please %2$srenew%3$s your license or purchase a new one %4$shere%5$s.'=>'La traducción automática de %1$s requiere una licencia activa. Por favor, %2$srenueva%3$s tu licencia o compra una nueva %4$saquí%5$s.','You have less than 5,000 TranslatePress AI words remaining. To continue automatically translating your website, please %spurchase additional AI words at a discount from your account%s.'=>'Te quedan menos de 5.000 palabras de TranslatePress AI. Para seguir traduciendo automáticamente tu sitio web, por favor %scompra palabras adicionales de AI con descuento desde tu cuenta%s.','You do not have a valid license for <strong>TranslatePress</strong>. %1$sGet one for free%2$s to get access to TranslatePress AI.'=>'No tienes una licencia válida para <strong>TranslatePress</strong>. %1$sObtén una gratis%2$s para obtener acceso a TranslatePress AI.',' Error: '=>' Error: ','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Learn more</a>.'=>'<strong>NUEVO:</strong> ¡El complemento <strong>Different Domain per Language</strong> ya está aquí! Impulsa tu SEO global y crea una experiencia local con dominios específicos para cada país como .de o .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Más información</a>.','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. Upgrade to <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business or Developer</a> to access it + more premium perks!'=>'<strong>NUEVO:</strong> ¡El complemento <strong>Different Domain per Language</strong> ya está aquí! Impulsa tu SEO global y crea una experiencia local con dominios específicos para cada país como .de o .fr. Actualiza a <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business o Developer</a> para acceder a él y más beneficios premium.','The daily quota for machine translation characters exceeded. Please check the <strong>TranslatePress -> <a href="%s">Automatic Translation</a></strong> page for more information.'=>'Se excedió la cuota diaria de caracteres de traducción automática. Por favor, revisa la página <strong>TranslatePress -> <a href="%s">Traducción automática</a></strong> para más información.','Marketing optin'=>'Opt-in de marketing','Opt in to our security and feature updates notifications, and non-sensitive diagnostic tracking.'=>'Acepta recibir nuestras notificaciones de actualizaciones de seguridad y funciones, y el seguimiento diagnóstico no sensible.','TranslatePress Preferred User Language'=>'Idioma preferido del usuario de TranslatePress','Preferred language to navigate the site'=>'Idioma preferido para navegar el sitio','The language is automatically set based by the last visited language by the user.'=>'El idioma se establece automáticamente según el último idioma visitado por el usuario.','Always use this language'=>'Usar siempre este idioma','By checking this setting the preferred language will remain the one selected above, without the possibility of being changed in the frontend.<br>This language will be used in different operations such as sending email to the user.'=>'Al marcar esta configuración, el idioma preferido permanecerá como el seleccionado arriba, sin posibilidad de cambiarse en el frontend.<br>Este idioma se utilizará en diferentes operaciones, como el envío de correos electrónicos al usuario.','Hello! Seems like you\'ve been using <strong>TranslatePress</strong> for a while now to translate your website. That\'s awesome! '=>'¡Hola! Parece que llevas un tiempo usando <strong>TranslatePress</strong> para traducir tu sitio web. ¡Eso es genial! ','If you can spare a few moments to rate it on WordPress.org it would help us a lot (and boost my motivation).'=>'Si puedes dedicar unos momentos para calificarlo en WordPress.org, nos ayudaría mucho (y aumentaría mi motivación).','~ Razvan, developer of TranslatePress'=>'~ Razvan, desarrollador de TranslatePress','Rate TranslatePress on WordPress.org plugin page'=>'Calificar TranslatePress en la página del plugin en WordPress.org','Ok, I will gladly help!'=>'¡Ok, con gusto ayudo!','No, thanks.'=>'No, gracias.','Full Language Names'=>'Nombres completos de idioma','Short Language Names'=>'Nombres cortos de idioma','Flags with Full Language Names'=>'Banderas con nombres completos de idioma','Flags with Short Language Names'=>'Banderas con nombres cortos de idioma','Only Flags'=>'Solo banderas','Full Language Names No HTML'=>'Nombres completos de idioma sin HTML','Bottom Right'=>'Abajo a la derecha','Bottom Left'=>'Abajo a la izquierda','Top Right'=>'Arriba a la derecha','Top Left'=>'Arriba a la izquierda','Dark'=>'Oscuro','Light'=>'Claro','Install & Activate'=>'Instalar y activar','Invalid language code. Please try again.'=>'Código de idioma no válido. Por favor, inténtalo de nuevo.','Language codes can contain only A-Z a-z 0-9 - _ characters. Check your language codes in TranslatePress General Settings.'=>'Los códigos de idioma solo pueden contener los caracteres A-Z a-z 0-9 - _. Verifica tus códigos de idioma en la configuración general de TranslatePress.','Error! Duplicate URL slug values.'=>'¡Error! Valores duplicados de slug de URL.','You cannot select two languages that have the same <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">iso code</a> but different formalities because doing so will lead to duplicate <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">hreflang tags</a>.'=>'No puedes seleccionar dos idiomas que tengan el mismo <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">código ISO</a> pero diferentes formalidades, porque hacerlo generará <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">etiquetas hreflang</a> duplicadas.','Duplicate language detected.<br>Each language can only be added once to ensure accurate translation management.<br> Please change the duplicate language entry and try again. '=>'Idioma duplicado detectado.<br>Cada idioma solo se puede agregar una vez para garantizar una gestión de traducciones precisa.<br> Cambia la entrada de idioma duplicada e inténtalo de nuevo. ','Current Language'=>'Idioma actual','Opposite Language'=>'Idioma opuesto','Addons'=>'Complementos','Settings'=>'Ajustes','Pro Features'=>'Funciones Pro','Activate License'=>'Activar licencia','Need Help?'=>'¿Necesitas ayuda?','Recent community discussions'=>'Discusiones recientes de la comunidad','Loading...'=>'Cargando...','Unable to load forum posts'=>'No se pueden cargar las entradas del foro','Ask a Question'=>'Hacer una pregunta','View All Topics'=>'Ver todos los temas','by'=>'por','Have a question?'=>'¿Tienes una pregunta?','Get help directly from the plugin developers, suggest improvements, or share your feedback!'=>'¡Obtén ayuda directamente de los desarrolladores del plugin, sugiere mejoras o comparte tus comentarios!','Tip for faster help:'=>'Consejo para obtener ayuda más rápida:','Include what you tried, what you expected, and what happened. Screenshots help!'=>'Incluye lo que intentaste, lo que esperabas y lo que sucedió. ¡Las capturas de pantalla ayudan!','Toggle support chat'=>'Alternar chat de soporte','Ask the community'=>'Preguntar a la comunidad','Close'=>'Cerrar','Empty feed response'=>'Respuesta vacía del feed','Unable to parse feed'=>'No se pudo analizar el feed','Just now'=>'Justo ahora','%d hour ago'=>'Hace %d hora' . "\0" . 'Hace %d horas','%d day ago'=>'Hace %d día' . "\0" . 'Hace %d días','Source'=>'Fuente','Srcset'=>'Srcset','Alt attribute'=>'Atributo alt','Title attribute'=>'Atributo title','Anchor link'=>'Enlace ancla','Placeholder attribute'=>'Atributo placeholder','Submit attribute'=>'Atributo submit','Text'=>'Texto','Video Poster'=>'Póster de video','plural form'=>'forma plural','one'=>'uno','few'=>'pocos','many'=>'muchos','other'=>'otro','Saved'=>'Guardado','Save'=>'Guardar','Saving translation...'=>'Guardando traducción...','You have unsaved changes!'=>'¡Tienes cambios sin guardar!','Discard changes'=>'Descartar cambios','Discard All'=>'Descartar todo','Loading Strings...'=>'Cargando cadenas...','Select string to translate...'=>'Selecciona una cadena para traducir...','Close Editor'=>'Cerrar editor','From'=>'De','To'=>'A','Add Media'=>'Añadir medios','Other languages'=>'Otros idiomas','Context'=>'Contexto','View Website As'=>'Ver sitio web como','Available in our Pro Versions'=>'Disponible en nuestras versiones Pro','Select or Upload Media'=>'Seleccionar o subir medios','Use this media'=>'Usar este medio','Translate'=>'Traducir','Translate entire block element'=>'Traducir todo el elemento del bloque','Split block to translate strings individually'=>'Dividir el bloque para traducir las cadenas de forma individual','Save changes to translation. Shortcut: CTRL(⌘) + S'=>'Guardar cambios en la traducción. Atajo: CTRL(⌘) + S','Navigate to next string in dropdown list. Shortcut: CTRL(⌘) + ALT + Right Arrow'=>'Navegar a la siguiente cadena en la lista desplegable. Atajo: CTRL(⌘) + ALT + Flecha derecha','Navigate to previous string in dropdown list. Shortcut: CTRL(⌘) + ALT + Left Arrow'=>'Navegar a la cadena anterior en la lista desplegable. Atajo: CTRL(⌘) + ALT + Flecha izquierda','Discard all changes. Shortcut: CTRL(⌘) + ALT + Z'=>'Descartar todos los cambios. Atajo: CTRL(⌘) + ALT + Z','Discard changes to this text box. To discard changes to all text boxes use shortcut: CTRL(⌘) + ALT + Z'=>'Descartar cambios en este cuadro de texto. Para descartar cambios en todos los cuadros de texto usa el atajo: CTRL(⌘) + ALT + Z','Dismiss tooltip'=>'Descartar sugerencia','Quick Intro'=>'Introducción rápida','Are you sure you want to split this phrase into smaller parts?'=>'¿Estás seguro de que quieres dividir esta frase en partes más pequeñas?','This string is not ready for translation yet. <br>Try again in a moment...'=>'Esta cadena aún no está lista para traducir.<br>Inténtalo de nuevo en un momento...','For this option to work, please update the Browse as other role add-on to the latest version.'=>'Para que esta opción funcione, actualiza el complemento Browse as other role a la última versión.','To translate slugs, please update the SEO Pack add-on to the latest version.'=>'Para traducir slugs, actualiza el complemento SEO Pack a la versión más reciente.','You can add a new language from <a href="%s">Settings->TranslatePress</a>'=>'Puedes agregar un nuevo idioma desde <a href="%s">Ajustes->TranslatePress</a>','However, you can still use TranslatePress to <strong style="background: #f5fb9d;">modify gettext strings</strong> available in your page.'=>'Sin embargo, aún puedes usar TranslatePress para <strong style="background: #f5fb9d;">modificar cadenas gettext</strong> disponibles en tu página.','Strings that are user-created cannot be modified, only those from themes and plugins.'=>'Las cadenas creadas por el usuario no se pueden modificar, solo las de temas y plugins.','Extra Translation Features'=>'Funciones extra de traducción','Support for 130+ Extra Languages'=>'Soporte para más de 130 idiomas adicionales','Access to TranslatePress AI'=>'Acceso a TranslatePress AI','Translate SEO Title, Description, Slug'=>'Traducir título SEO, descripción y slug','Publish only when translation is complete'=>'Publicar solo cuando la traducción esté completa','Translate by Browsing as User Role'=>'Traducir navegando como otro rol','Different Menu Items for each Language'=>'Elementos de menú diferentes para cada idioma','Upgrade to PRO'=>'Actualizar a PRO','Upgrade to PRO with our biggest discount of the year!'=>'¡Actualiza a PRO con nuestro mayor descuento del año!','This Black Friday, get access to these features and more at a fraction of the costs:'=>'Este Black Friday, obtén acceso a estas funciones y más por una fracción del costo:','No available suggestions'=>'No hay sugerencias disponibles','Suggestions from translation memory'=>'Sugerencias de la memoria de traducción','Click to Copy'=>'Clic para copiar','Human Translation'=>'Traducción humana','Machine Translation'=>'Traducción automática','Gettext File Translation'=>'Traducción de archivos Gettext','Text on this page is %s% translated into all languages.'=>'El texto de esta página está %s% traducido a todos los idiomas.','%1$s% of text on this page is translated into %2$s.'=>'%1$s% del texto de esta página está traducido al %2$s.','This page is %1$s% translated into %2$s.'=>'Esta página está %1$s% traducida al %2$s.','The slug that you are trying to edit is present in other slug types:%s%. Editing it will replace each occurrence, regardless of the current type.'=>'El slug que intentas editar está presente en otros tipos de slug:%s%. Al editarlo se reemplazará cada ocurrencia, independientemente del tipo actual.','Hover any text on the page, click %s,<br> then modify the translation in the sidebar.'=>'Pasa el cursor sobre cualquier texto de la página, haz clic en %s,<br> luego modifica la traducción en la barra lateral.','Don\'t forget to Save Translation. Use keyboard shortcut CTRL(⌘) + S'=>'No olvides guardar la traducción. Usa el atajo de teclado CTRL(⌘) + S','Switch language to see the translation changes directly on the page.'=>'Cambia de idioma para ver los cambios de traducción directamente en la página.','Search for any text in this page in the dropdown.'=>'Busca cualquier texto de esta página en el menú desplegable.','Your %s license has <span class="trp-license-status-emphasized">expired</span>.'=>'Tu licencia %s ha <span class="trp-license-status-emphasized">expirado</span>.','<strong>This Black Friday, renew your license at a special price</strong> to continue receiving access to product downloads, automatic updates, and support.'=>'<strong>Este Black Friday, renueva tu licencia a un precio especial</strong> para seguir recibiendo acceso a descargas de productos, actualizaciones automáticas y soporte.','Get Deal'=>'Obtener oferta','Please renew your license to continue receiving access to TranslatePress AI, premium addons, automatic updates and support.'=>'Por favor, renueva tu licencia para seguir recibiendo acceso a TranslatePress AI, complementos premium, actualizaciones automáticas y soporte.','Renew Now'=>'Renovar ahora','Your %s license was <span class="trp-license-status-emphasized">refunded</span>.'=>'Tu licencia %s fue <span class="trp-license-status-emphasized">reembolsada</span>.','Please purchase a new license to continue receiving access to TranslatePress AI, premium addons, automatic updates and support.'=>'Por favor, adquiere una licencia nueva para seguir recibiendo acceso a TranslatePress AI, complementos premium, actualizaciones automáticas y soporte.','Purchase a new license'=>'Comprar una nueva licencia','Your %s license is <span class="trp-license-status-emphasized">missing or invalid</span>.'=>'Tu licencia de %s está <span class="trp-license-status-emphasized">ausente o no válida</span>.','Please enter a valid license to get access to TranslatePress AI, premium addons, automatic updates and support. Need a license key? %1$sPurchase one now%2$s'=>'Por favor, ingresa una licencia válida para acceder a TranslatePress AI, complementos premium, actualizaciones automáticas y soporte. ¿Necesitas una clave de licencia? %1$sCompra una ahora%2$s','Enter a valid license'=>'Ingresar una licencia válida','Meta Information'=>'Información meta','String List'=>'Lista de cadenas','Gettext Strings'=>'Cadenas gettext','Images'=>'Imágenes','Videos'=>'Videos','Audios'=>'Audios','Dynamically Added Strings'=>'Cadenas agregadas dinámicamente','Translation Editor'=>'Editor de traducciones','Edit translations by visually selecting them on each site page'=>'Edita las traducciones seleccionándolas visualmente en cada página del sitio','String Translation'=>'Traducción de cadenas','Edit url slug translations, plugins and theme translation (emails, forms etc.)'=>'Editar traducciones de slugs de URL, plugins y traducción de temas (correos electrónicos, formularios, etc.)','Current User'=>'Usuario actual','Logged Out'=>'Desconectado','Translate Page'=>'Traducir página','Add a New Language'=>'Agregar un nuevo idioma','Your License is Invalid'=>'Tu licencia no es válida','Get More AI Words (%d left)'=>'Obtener más palabras de IA (quedan %d)','Opens post in the translation editor. Post must be saved as draft or published beforehand.'=>'Abre la entrada en el editor de traducción. La entrada debe estar guardada como borrador o publicada previamente.','Security check'=>'Comprobación de seguridad','<strong>Warning:</strong> Some strings have possibly incorrectly encoded characters. This may result in breaking the queries, rendering the page untranslated in live mode. Consider revising the following strings or their method of outputting.'=>'<strong>Advertencia:</strong> Algunas cadenas tienen caracteres posiblemente codificados de forma incorrecta. Esto puede romper las consultas y hacer que la página no se traduzca en el modo en vivo. Considera revisar las siguientes cadenas o su método de salida.','IMPORTANT: It is strongly recommended to first backup the database!'=>'IMPORTANTE: ¡Se recomienda encarecidamente hacer primero una copia de seguridad de la base de datos!','Are you sure you want to continue?'=>'¿Estás seguro de que quieres continuar?','TranslatePress data update'=>'Actualización de datos de TranslatePress','We need to update your translations database to the latest version.'=>'Necesitamos actualizar tu base de datos de traducciones a la última versión.','Updating will allow editing translations of localized text from plugins and theme. Existing translation will still work as expected.'=>'La actualización permitirá editar las traducciones del texto localizado de plugins y el tema. La traducción existente 